-- Функция для безопасной проверки объекта
local function IsValidObject(obj)
    return obj and obj.Parent and not obj.Parent:IsA("Debris")
end

-- Функция для автоматического взаимодействия с ProximityPrompt
local function SetupAutoInteract()
    if autoInteractConnection then
        autoInteractConnection:Disconnect()
        autoInteractConnection = nil
    end
    
    if not autoInteract then
        return
    end
    
    -- Функция для проверки, является ли объект hiding spot
    local function IsHidingSpot(obj)
        if not IsValidObject(obj) then return false end
        
        -- Проверяем имя объекта
        local objName = obj.Name
        for _, hidingName in pairs(HSList) do
            if objName == hidingName then
                return true
            end
        end
        
        -- Проверяем родителей
        local parent = obj.Parent
        local depth = 0
        while parent and parent ~= workspace and depth < 10 do
            for _, hidingName in pairs(HSList) do
                if parent.Name == hidingName then
                    return true
                end
            end
            parent = parent.Parent
            depth = depth + 1
        end
        
        return false
    end
    
    -- Функция для обработки промпта
    local function HandlePrompt(prompt)
        if not autoInteract or not IsValidObject(prompt) then return end
        if not prompt:IsA("ProximityPrompt") then return end
        
        -- Проверяем, включен ли промпт
        if not prompt.Enabled then return end
        
        -- Игнорируем hiding spots
        if IsHidingSpot(prompt.Parent) then
            return
        end
        
        -- Игнорируем промпты с текстом "Hide", "Exit", "Leave"
        local actionText = prompt.ActionText:lower()
        if actionText:find("hide") or actionText:find("exit") or actionText:find("leave") then
            return
        end
        
        -- Игнорируем промпты закрытия
        if actionText:find("close") or actionText:find("shut") then
            return
        end
        
        -- Если включен Instant Interact, устанавливаем HoldDuration в 0
        if instantInteract then
            pcall(function()
                prompt.HoldDuration = 0
            end)
        end
        
        -- Автоматически активируем промпт
        task.spawn(function()
            pcall(function()
                if prompt.Enabled and IsValidObject(prompt) then
                    fireproximityprompt(prompt)
                end
            end)
        end)
    end
    
    -- Подключаемся к событию появления промптов
    autoInteractConnection = ProximityPromptService.PromptShown:Connect(function(prompt)
        HandlePrompt(prompt)
    end)
    
    -- Обрабатываем уже существующие промпты
    pcall(function()
        for _, descendant in pairs(workspace:GetDescendants()) do
            if descendant:IsA("ProximityPrompt") and descendant.Enabled then
                HandlePrompt(descendant)
            end
        end
    end)
end

-- Функция для мгновенного взаимодействия
local function SetupInstantInteract()
    -- Очищаем старые подключения
    for _, connection in pairs(promptConnections) do
        pcall(function() connection:Disconnect() end)
    end
    promptConnections = {}
    
    if not instantInteract then return end
    
    -- Функция для установки HoldDuration в 0
    local function MakeInstant(prompt)
        if prompt:IsA("ProximityPrompt") then
            pcall(function()
                prompt.HoldDuration = 0
            end)
        end
    end
    
    -- Применяем к существующим промптам
    pcall(function()
        for _, descendant in pairs(workspace:GetDescendants()) do
            MakeInstant(descendant)
        end
    end)
    
    -- Отслеживаем новые промпты
    table.insert(promptConnections, workspace.DescendantAdded:Connect(function(descendant)
        if instantInteract then
            MakeInstant(descendant)
        end
    end))
end

-- Функция для получения читаемого имени монстра
local function GetEntityDisplayName(name)
    local displayNames = {
        ["RushMoving"] = "Rush",
        ["RushNew"] = "Rush",
        ["AmbushMoving"] = "Ambush",
        ["SeekMoving"] = "Seek",
        ["SeekRig"] = "Seek",
        ["FigureRig"] = "Figure",
        ["GiggleCeiling"] = "Giggle",
        ["SallyMoving"] = "Sally",
        ["GrumbleRig"] = "Grumble",
        ["A60"] = "A-60",
        ["A120"] = "A-120"
    }
    return displayNames[name] or name
end

-- Улучшенная функция для проверки, является ли объект монстром
local function IsEntity(obj)
    if not IsValidObject(obj) or not obj:IsA("Model") then
        return false
    end
    
    local name = obj.Name
    for _, entityName in pairs(EntityNames) do
        if name == entityName then
            return true
        end
    end
    return false
end

local function ToggleRemote(name, state)
    pcall(function()
        local remote = Remotes:FindFirstChild(name) or _G[name .. "_Storage"]
        if state then
            if remote then
                _G[name .. "_Storage"] = remote
                remote.Parent = nil
            end
        else
            local storage = _G[name .. "_Storage"]
            if storage then
                storage.Parent = Remotes
            end
        end
    end)
end

local function Cleanup(obj, data)
    pcall(function()
        if data.Highlight then data.Highlight:Destroy() end
        if data.Box then data.Box:Destroy() end
        if data.Bill then data.Bill:Destroy() end
    end)
    activeESPs[obj] = nil
end

local function CreateESP(obj, name, type)
    if not IsValidObject(obj) or activeESPs[obj] then return end
 
    local objN = obj.Name
 
    if objN == "LiveHintBook" or objN == "FigureRig" or objN == "LiveBreakerPolePickup" or objN == "ElectricalKeyObtain" then
        local displayName = (objN == "LiveHintBook" and "Book") or
                            (objN == "FigureRig" and "Figure") or
                            (objN == "LiveBreakerPolePickup" and "Breaker") or
                            (objN == "ElectricalKeyObtain" and "Electrical Key")
        activeESPs[obj] = { Name = displayName, Type = type }
        return
    end
    local lowerN = objN:lower()
    if lowerN:find("bookcase") or lowerN:find("modular_bookshelf") then
        return
    end
    activeESPs[obj] = { Name = name, Type = type }
end

-- Улучшенная функция поиска монстров с оповещениями
local function ScanForEntities()
    if not entityESP_enabled then 
        if next(detectedEntities) then
            detectedEntities = {}
        end
        return 
    end
    
    local foundEntities = {}
    
    -- Поиск в workspace напрямую
    pcall(function()
        for _, obj in pairs(workspace:GetChildren()) do
            if IsEntity(obj) then
                local displayName = GetEntityDisplayName(obj.Name)
                CreateESP(obj, displayName, "Entity")
                foundEntities[obj] = true
                
                if entityNotifications_enabled and not detectedEntities[obj] then
                    detectedEntities[obj] = true
                    
                    Notification:Notify({
                        Title = "ENTITY SPAWNED!",
                        Content = displayName .. " has been detected!",
                        Icon = "alert-triangle",
                        Duration = 5
                    })
                    
                    pcall(function()
                        local sound = Instance.new("Sound", workspace)
                        sound.SoundId = "rbxassetid://6518811702"
                        sound.Volume = 0.5
                        sound:Play()
                        Debris:AddItem(sound, 2)
                    end)
                end
            end
        end
    end)
    
    -- Поиск в CurrentRooms
    local rooms = workspace:FindFirstChild("CurrentRooms")
    if rooms then
        pcall(function()
            for _, room in pairs(rooms:GetChildren()) do
                if not IsValidObject(room) then continue end
                
                for _, child in pairs(room:GetChildren()) do
                    if IsEntity(child) then
                        local displayName = GetEntityDisplayName(child.Name)
                        CreateESP(child, displayName, "Entity")
                        foundEntities[child] = true
                        
                        if entityNotifications_enabled and not detectedEntities[child] then
                            detectedEntities[child] = true
                            
                            Notification:Notify({
                                Title = "ENTITY SPAWNED!",
                                Content = displayName .. " has been detected!",
                                Icon = "alert-triangle",
                                Duration = 5
                            })
                            
                            pcall(function()
                                local sound = Instance.new("Sound", workspace)
                                sound.SoundId = "rbxassetid://6518811702"
                                sound.Volume = 0.5
                                sound:Play()
                                Debris:AddItem(sound, 2)
                            end)
                        end
                    end
                    
                    -- Проверяем один уровень вглубь
                    if IsValidObject(child) and (child:IsA("Model") or child:IsA("Folder")) then
                        for _, subChild in pairs(child:GetChildren()) do
                            if IsEntity(subChild) then
                                local displayName = GetEntityDisplayName(subChild.Name)
                                CreateESP(subChild, displayName, "Entity")
                                foundEntities[subChild] = true
                                
                                if entityNotifications_enabled and not detectedEntities[subChild] then
                                    detectedEntities[subChild] = true
                                    
                                    Notification:Notify({
                                        Title = "ENTITY SPAWNED!",
                                        Content = displayName .. " has been detected!",
                                        Icon = "alert-triangle",
                                        Duration = 5
                                    })
                                    
                                    pcall(function()
                                        local sound = Instance.new("Sound", workspace)
                                        sound.SoundId = "rbxassetid://6518811702"
                                        sound.Volume = 0.5
                                        sound:Play()
                                        Debris:AddItem(sound, 2)
                                    end)
                                end
                            end
                        end
                    end
                end
            end
        end)
    end
    
    -- Очищаем список от исчезнувших монстров
    for entity, _ in pairs(detectedEntities) do
        if not foundEntities[entity] or not IsValidObject(entity) then
            detectedEntities[entity] = nil
        end
    end
end

-- Оптимизированное сканирование объектов
task.spawn(function()
    while running do
        local currentTime = tick()
        
        -- Сканируем комнаты только раз в секунду
        if currentTime - lastRoomScan >= ROOM_SCAN_INTERVAL then
            lastRoomScan = currentTime
            
            local rooms = workspace:FindFirstChild("CurrentRooms")
            if rooms then
                pcall(function()
                    for _, room in pairs(rooms:GetChildren()) do
                        if not IsValidObject(room) or not running then break end
                        
                        -- Для дверей
                        if doorESP_enabled then
                            local doorModel = room:FindFirstChild("Door")
                            if doorModel and doorModel:IsA("Model") then
                                local doorPart = doorModel:FindFirstChild("Door")
                                if doorPart and doorPart:IsA("BasePart") then
                                    CreateESP(doorPart, "Next Door", "Door")
                                end
                            end
                        end
                        
                        -- Остальные объекты (оптимизировано)
                        local descendants = room:GetDescendants()
                        for i = 1, #descendants do
                            if not running then break end
                            
                            local child = descendants[i]
                            if not IsValidObject(child) then continue end
                            
                            local n = child.Name
                         
                            if objESP_enabled and table.find(ObjList, n) then
                                local d = (n == "KeyObtain" and "Key") or
                                          (n == "LeverForGate" and "Lever") or
                                          (n == "LiveHintBook" and "Book") or
                                          (n == "LiveBreakerPolePickup" and "Breaker") or
                                          (n == "ElectricalKeyObtain" and "Electrical Key") or n
                                CreateESP(child, d, "Objective")
                            elseif goldESP_enabled and n == "GoldPile" then
                                CreateESP(child, "Gold", "Gold")
                            elseif itemESP_enabled and table.find(ItemList, n) then
                                CreateESP(child, n, "Item")
                            elseif hidingESP_enabled and table.find(HSList, n) then
                                CreateESP(child, n, "Hiding")
                            elseif shedESP_enabled and n == "Toolshed_Small" then
                                CreateESP(child, "Tool Shed", "Shed")
                            end
                            
                            -- Пауза каждые 50 объектов для предотвращения лагов
                            if i % 50 == 0 then
                                task.wait()
                            end
                        end
                        
                        task.wait(0.01)
                    end
                end)
            end
        end
        
        -- Сканирование монстров
        ScanForEntities()
     
        -- Player ESP
        if playerESP_enabled then
            pcall(function()
                for _, plr in pairs(Players:GetPlayers()) do
                    if plr ~= LocalPlayer then
                        local char = plr.Character
                        if char and IsValidObject(char) then
                            CreateESP(char, plr.DisplayName or plr.Name, "Player")
                        end
                    end
                end
            end)
        end
     
        task.wait(0.5)
    end
end)

-- Оптимизированная функция обновления ESP
local function UpdateESP()
    if not running then return end
    
    local rainbow = Color3.fromHSV(tick() % 5 / 5, 1, 1)
    local char = LocalPlayer.Character
    local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Collision"))
    
    if not root or not IsValidObject(root) then return end
    
    for obj, data in pairs(activeESPs) do
        pcall(function()
            local isEnabled = (data.Type == "Door" and doorESP_enabled) or
                              (data.Type == "Objective" and objESP_enabled) or
                              (data.Type == "Entity" and entityESP_enabled) or
                              (data.Type == "Gold" and goldESP_enabled) or
                              (data.Type == "Item" and itemESP_enabled) or
                              (data.Type == "Hiding" and hidingESP_enabled) or
                              (data.Type == "Shed" and shedESP_enabled) or
                              (data.Type == "Player" and playerESP_enabled)
            
            if not IsValidObject(obj) or not isEnabled then
                Cleanup(obj, data)
                return
            end
            
            local targetPos
            if obj:IsA("Model") then
                local success, result = pcall(function() return obj:GetPivot().Position end)
                targetPos = success and result or nil
            elseif obj:IsA("BasePart") then
                targetPos = obj.Position
            end
            
            if not targetPos then 
                Cleanup(obj, data)
                return 
            end
         
            local dist = (root.Position - targetPos).Magnitude
            if dist > maxDistance then
                if data.Highlight then data.Highlight.Enabled = false end
                if data.Box then data.Box.Visible = false end
                if data.Bill then data.Bill.Enabled = false end
                return
            end
            
            local _, onScreen = Camera:WorldToViewportPoint(targetPos)
            if onScreen then
                local color = doorESP_color
                if data.Type == "Entity" then color = entityESP_color
                elseif data.Type == "Player" then color = playerESP_color
                elseif data.Type == "Gold" then color = goldESP_color
                elseif data.Type == "Item" then color = itemESP_color
                elseif data.Type == "Objective" then color = objESP_color
                elseif data.Type == "Hiding" then color = hidingESP_color
                elseif data.Type == "Shed" then color = shedESP_color end
                if rainbowESP then color = rainbow end
                
                if data.Type == "Door" then
                    if not data.Box then
                        data.Box = Instance.new("BoxHandleAdornment", obj)
                        data.Box.AlwaysOnTop = true
                        data.Box.Adornee = obj
                        data.Box.ZIndex = 5
                    end
                    data.Box.Visible = true
                    data.Box.Size = obj.Size
                    data.Box.Color3 = color
                    data.Box.Transparency = 0.7
                else
                    if not data.Highlight then 
                        data.Highlight = Instance.new("Highlight", obj)
                    end
                    data.Highlight.Enabled = true
                    data.Highlight.FillColor = color
                    data.Highlight.OutlineColor = color
                    data.Highlight.FillTransparency = 0.5
                end
                
                if not data.Bill then
                    data.Bill = Instance.new("BillboardGui", obj)
                    data.Bill.AlwaysOnTop = true
                    data.Bill.Size = UDim2.new(0, 150, 0, 40)
                    local txt = Instance.new("TextLabel", data.Bill)
                    txt.BackgroundTransparency = 1
                    txt.Size = UDim2.new(1, 0, 1, 0)
                    txt.Font = "SourceSansBold"
                    txt.Name = "L"
                    txt.TextStrokeTransparency = 0
                end
                
                data.Bill.Enabled = enableText
                data.Bill.StudsOffset = Vector3.new(0, textOffsetY, 0)
                local lbl = data.Bill:FindFirstChild("L")
                if lbl then
                    lbl.TextColor3 = color
                    lbl.TextSize = textSize
                    lbl.Text = data.Name .. " [" .. math.floor(dist) .. "]"
                end
            else
                if data.Highlight then data.Highlight.Enabled = false end
                if data.Box then data.Box.Visible = false end
                if data.Bill then data.Bill.Enabled = false end
            end
        end)
    end
end

-- Функция для обновления FOV
local function UpdateFOV()
    if fovConnection then
        fovConnection:Disconnect()
        fovConnection = nil
    end
    
    if customFOVEnabled then
        fovConnection = RunService.RenderStepped:Connect(function()
            pcall(function()
                if customFOVEnabled and Camera then
                    Camera.FieldOfView = fovValue
                end
            end)
        end)
    else
        pcall(function()
            Camera.FieldOfView = originalFOV
        end)
    end
end

local connection = RunService.RenderStepped:Connect(function()
    pcall(UpdateESP)
end)

