        Name = "Auto Interact",
        Callback = function(v)
            autoInteract = v
            SetupAutoInteract()
            
            if v then
                Notification:Notify({
                    Title = "Auto Interact",
                    Content = "Auto Interact enabled",
                    Icon = "check"
                })
            else
                Notification:Notify({
                    Title = "Auto Interact",
                    Content = "Auto Interact disabled",
                    Icon = "info"
                })
            end
        end
    })
    Player:AddToggle({
        Name = "Instant Interact",
        Callback = function(v)
            instantInteract = v
            SetupInstantInteract()
            
            if v then
                Notification:Notify({
                    Title = "Instant Interact",
                    Content = "Instant Interact enabled",
                    Icon = "zap"
                })
            else
                Notification:Notify({
                    Title = "Instant Interact",
                    Content = "Instant Interact disabled",
                    Icon = "info"
                })
            end
        end
    })
    Player:AddToggle({
        Name = "Toggle Jump",
        Callback = function(v)
            toggleJump = v
            pcall(function()
                local char = workspace:FindFirstChild(LocalPlayer.Name)
                if char then
                    char:SetAttribute("CanJump", v)
                end
            end)
        end
    })
    Player:AddToggle({
        Name = "Toggle Slide",
        Callback = function(v)
            toggleSlide = v
            pcall(function()
                local char = workspace:FindFirstChild(LocalPlayer.Name)
                if char then
                    char:SetAttribute("CanSlide", v)
                end
            end)
        end
    })
    local Visuals = Main:AddSection({
        Position = 'left',
        Name = "VISUALS"
    });
    Visuals:AddToggle({
        Name = "Fullbright",
        Callback = function(v)
            fullbrightEnabled = v
            pcall(function()
                Lighting.ClockTime = v and 12 or 14
                Lighting.GlobalShadows = not v
                Lighting.Brightness = v and brightness or 1
            end)
        end
    })
    Visuals:AddSlider({
        Name = "Fullbright Intensity",
        Default = 2,
        Min = 1,
        Max = 10,
        Callback = function(v)
            brightness = v
            if fullbrightEnabled then
                pcall(function()
                    Lighting.Brightness = v
                end)
            end
        end
    })
    Visuals:AddToggle({
        Name = "Custom FOV",
        Callback = function(v)
            customFOVEnabled = v
            UpdateFOV()
            
            if v then
                Notification:Notify({
                    Title = "Custom FOV",
                    Content = "Custom FOV enabled - Value: " .. fovValue,
                    Icon = "eye"
                })
            else
                Notification:Notify({
                    Title = "Custom FOV",
                    Content = "FOV reset to default",
                    Icon = "eye-off"
                })
            end
        end
    })
    Visuals:AddSlider({
        Name = "FOV Value",
        Default = 70,
        Min = 50,
        Max = 120,
        Callback = function(v)
            fovValue = v
            if customFOVEnabled then
                pcall(function()
                    Camera.FieldOfView = v
                end)
            end
        end
    })
    
    local AntiEntities = Main:AddSection({
        Position = 'right',
        Name = "ANTI-ENTITIES"
    });
    AntiEntities:AddToggle({
        Name = "Anti A-90",
        Callback = function(v) antiA90 = v; ToggleRemote("A90", v) end
    })
    AntiEntities:AddToggle({
        Name = "Anti Dread",
        Callback = function(v) antiDread = v; ToggleRemote("Dread", v) end
    })
    AntiEntities:AddToggle({
        Name = "Anti Screech",
        Callback = function(v) antiScreech = v; ToggleRemote("Screech", v) end
    })
    AntiEntities:AddToggle({
        Name = "Anti Giggle",
        Callback = function(v) antiGiggle = v; ToggleRemote("Giggle", v) end
    })
    AntiEntities:AddToggle({
        Name = "Anti Haste",
        Callback = function(v) antiHaste = v; ToggleRemote("Haste", v) end
    })
    AntiEntities:AddToggle({
        Name = "Anti CamShake",
        Callback = function(v)
            antiCamShake = v
            local list = {"CamShake", "CamShakeClient", "CamShakeRelative", "CamShakeRelativeClient"}
            for _, name in pairs(list) do ToggleRemote(name, v) end
        end
    })
end
do
    local ESPSettings = ESP:AddSection({
        Position = 'left',
        Name = "ESP OPTIONS"
    });
    local ESPConfig = ESP:AddSection({
        Position = 'right',
        Name = "SETTINGS"
    });
    local DoorESP = ESPSettings:AddToggle({
        Name = "Door ESP",
        Option = true,
        Callback = function(v) doorESP_enabled = v end
    })
    DoorESP.Option:AddColorPicker({
        Name = "Door Color",
        Default = Color3.fromRGB(120, 0, 0),
        Callback = function(c) doorESP_color = c end
    })
    local ObjESP = ESPSettings:AddToggle({
        Name = "Objective ESP",
        Option = true,
        Callback = function(v) objESP_enabled = v end
    })
    ObjESP.Option:AddColorPicker({
        Name = "Objective Color",
        Default = Color3.fromRGB(0, 0, 255),
        Callback = function(c) objESP_color = c end
    })
    local EntityESP = ESPSettings:AddToggle({
        Name = "Entity Highlight",
        Option = true,
        Callback = function(v) entityESP_enabled = v end
    })
    EntityESP.Option:AddColorPicker({
        Name = "Entity Color",
        Default = Color3.fromRGB(255, 0, 0),
        Callback = function(c) entityESP_color = c end
    })
    local GoldESP = ESPSettings:AddToggle({
        Name = "Gold Highlight",
        Option = true,
        Callback = function(v) goldESP_enabled = v end
    })
    GoldESP.Option:AddColorPicker({
        Name = "Gold Color",
        Default = Color3.fromRGB(255, 225, 0),
        Callback = function(c) goldESP_color = c end
    })
    local ItemESP = ESPSettings:AddToggle({
        Name = "Item Highlight",
        Option = true,
        Callback = function(v) itemESP_enabled = v end
    })
    ItemESP.Option:AddColorPicker({
        Name = "Item Color",
        Default = Color3.fromRGB(0, 255, 255),
        Callback = function(c) itemESP_color = c end
    })
    local HidingESP = ESPSettings:AddToggle({
        Name = "Hiding ESP",
        Option = true,
        Callback = function(v) hidingESP_enabled = v end
    })
    HidingESP.Option:AddColorPicker({
        Name = "Hiding Color",
        Default = Color3.fromRGB(100, 100, 100),
        Callback = function(c) hidingESP_color = c end
    })
    local ShedESP = ESPSettings:AddToggle({
        Name = "ToolShed ESP",
        Option = true,
        Callback = function(v) shedESP_enabled = v end
    })
    ShedESP.Option:AddColorPicker({
        Name = "Shed Color",
        Default = Color3.fromRGB(139, 69, 19),
        Callback = function(c) shedESP_color = c end
    })
    local PlayerESP = ESPSettings:AddToggle({
        Name = "Player ESP",
        Option = true,
        Callback = function(v) playerESP_enabled = v end
    })
    PlayerESP.Option:AddColorPicker({
        Name = "Player Color",
        Default = Color3.fromRGB(0, 255, 0),
        Callback = function(c) playerESP_color = c end
    })
    
    ESPConfig:AddToggle({
        Name = "Entity Notifications",
        Callback = function(v) 
            entityNotifications_enabled = v 
            
            if v then
                Notification:Notify({
                    Title = "Entity Notifications",
                    Content = "Entity spawn notifications enabled",
                    Icon = "bell"
                })
            else
                detectedEntities = {}
                Notification:Notify({
                    Title = "Entity Notifications",
                    Content = "Entity spawn notifications disabled",
                    Icon = "bell-off"
                })
            end
        end
    })
    
    ESPConfig:AddToggle({
        Name = "Rainbow ESP",
        Callback = function(v) rainbowESP = v end
    })
    ESPConfig:AddToggle({
        Name = "Enable Text",
        Callback = function(v) enableText = v end
    })
    ESPConfig:AddSlider({
        Name = "Text Size",
        Default = 29,
        Min = 10,
        Max = 40,
        Callback = function(v) textSize = v end
    })
    ESPConfig:AddSlider({
        Name = "Text Offset Y",
        Default = 0.2,
        Min = -5,
        Max = 15,
        Callback = function(v) textOffsetY = v end
    })
    ESPConfig:AddSlider({
        Name = "Max ESP Distance",
        Default = 1000,
        Min = 50,
        Max = 5000,
        Callback = function(v) maxDistance = v end
    })
end
do
    local Menu = Settings:AddSection({
        Position = 'left',
        Name = "MENU"
    });
    Menu:AddButton({
        Name = "Unload",
        Callback = function()
            running = false
            
            pcall(function() connection:Disconnect() end)
            
            -- Очистка Auto Interact
            if autoInteractConnection then
                pcall(function() autoInteractConnection:Disconnect() end)
            end
            for _, conn in pairs(promptConnections) do
                pcall(function() conn:Disconnect() end)
            end
            
            -- Отключаем FOV
            if fovConnection then
                pcall(function() fovConnection:Disconnect() end)
            end
            pcall(function()
                Camera.FieldOfView = originalFOV
            end)
            
            -- Очистка
            detectedEntities = {}
            
            for obj, data in pairs(activeESPs) do 
                Cleanup(obj, data)
            end
            
            Notification:Notify({
                Title = "Yami.SC",
                Content = "Script unloaded successfully",
                Icon = "info"
            })
        end,
    })
end

